CREATE TABLE IF NOT EXISTS "accounts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Primary address, which is also the login. Compared case-insensitively on the domain part at minimum.
	"email_address" VARCHAR(320) NOT NULL UNIQUE,
	-- Name that appears in the From header of outgoing mail.
	"display_name" VARCHAR(160) NOT NULL,
	-- Argon2 or bcrypt digest. Never the password, and never reversible.
	"password_hash" VARCHAR(255) NOT NULL,
	-- IANA zone used to group the message list into Today and Yesterday, which is a local-calendar question.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- Storage allowance. Enforced at delivery, because rejecting at SMTP time is far kinder than accepting mail you cannot store.
	"quota_bytes" BIGINT NOT NULL DEFAULT 16106127360,
	-- Current usage, maintained incrementally on delivery and deletion. Summing message sizes to render a quota bar would scan the largest table in the schema.
	"used_bytes" BIGINT NOT NULL DEFAULT 0,
	-- active | suspended | over_quota | closed. over_quota is separate from suspended because incoming mail is bounced while outgoing may still be allowed.
	"status" VARCHAR(16) NOT NULL DEFAULT 'active',
	-- Account creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "accounts" IS 'A mailbox and its owner. The quota counter is deliberately denormalised: it is read on every delivery and shown on every page, and it is the one number that must never require an aggregate.';
COMMENT ON COLUMN "accounts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "accounts"."email_address" IS 'Primary address, which is also the login. Compared case-insensitively on the domain part at minimum.';
COMMENT ON COLUMN "accounts"."display_name" IS 'Name that appears in the From header of outgoing mail.';
COMMENT ON COLUMN "accounts"."password_hash" IS 'Argon2 or bcrypt digest. Never the password, and never reversible.';
COMMENT ON COLUMN "accounts"."timezone" IS 'IANA zone used to group the message list into Today and Yesterday, which is a local-calendar question.';
COMMENT ON COLUMN "accounts"."quota_bytes" IS 'Storage allowance. Enforced at delivery, because rejecting at SMTP time is far kinder than accepting mail you cannot store.';
COMMENT ON COLUMN "accounts"."used_bytes" IS 'Current usage, maintained incrementally on delivery and deletion. Summing message sizes to render a quota bar would scan the largest table in the schema.';
COMMENT ON COLUMN "accounts"."status" IS 'active | suspended | over_quota | closed. over_quota is separate from suspended because incoming mail is bounced while outgoing may still be allowed.';
COMMENT ON COLUMN "accounts"."created_at" IS 'Account creation time.';

CREATE TABLE IF NOT EXISTS "labels" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owner. Labels are per-mailbox; there is no shared namespace.
	"account_id" BIGINT NOT NULL,
	-- Label text as typed. Nesting is expressed through parent_label_id rather than by parsing slashes out of this.
	"name" VARCHAR(120) NOT NULL,
	-- Parent for nested labels. Null at the top level. Nesting is presentation only — a message with a child label is not implicitly in the parent.
	"parent_label_id" BIGINT,
	-- system | user. System labels such as INBOX, SENT, TRASH, SPAM, STARRED and UNREAD cannot be renamed or deleted.
	"label_type" VARCHAR(16) NOT NULL DEFAULT 'user',
	-- Hex swatch shown in the sidebar. Null uses the default.
	"color" VARCHAR(9),
	-- Hidden from the sidebar but still applied, which is how rarely used labels stay usable without cluttering the list.
	"is_hidden" BOOLEAN NOT NULL DEFAULT false,
	-- Manual ordering in the sidebar, because alphabetical is not what people want.
	"sort_order" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "labels" IS 'A tag, not a directory. Because a label is a tag, a message can carry several at once and moving it between labels is an insert and a delete in message_labels rather than a move of the message itself.';
COMMENT ON COLUMN "labels"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "labels"."account_id" IS 'Owner. Labels are per-mailbox; there is no shared namespace.';
COMMENT ON COLUMN "labels"."name" IS 'Label text as typed. Nesting is expressed through parent_label_id rather than by parsing slashes out of this.';
COMMENT ON COLUMN "labels"."parent_label_id" IS 'Parent for nested labels. Null at the top level. Nesting is presentation only — a message with a child label is not implicitly in the parent.';
COMMENT ON COLUMN "labels"."label_type" IS 'system | user. System labels such as INBOX, SENT, TRASH, SPAM, STARRED and UNREAD cannot be renamed or deleted.';
COMMENT ON COLUMN "labels"."color" IS 'Hex swatch shown in the sidebar. Null uses the default.';
COMMENT ON COLUMN "labels"."is_hidden" IS 'Hidden from the sidebar but still applied, which is how rarely used labels stay usable without cluttering the list.';
COMMENT ON COLUMN "labels"."sort_order" IS 'Manual ordering in the sidebar, because alphabetical is not what people want.';

CREATE UNIQUE INDEX "uq_labels_account_name"
ON "labels" ("account_id", "name");
CREATE INDEX "idx_labels_account_parent"
ON "labels" ("account_id", "parent_label_id");

CREATE TABLE IF NOT EXISTS "threads" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Mailbox the thread belongs to. Threads are per-account: two recipients of the same exchange have their own threads with their own state.
	"account_id" BIGINT NOT NULL,
	-- Subject with Re: and Fwd: prefixes stripped. Used as a weak threading signal when References headers are missing, which for mail from web forms is common.
	"subject_normalised" VARCHAR(500) NOT NULL,
	-- Cached size of the thread, so a list view never counts children.
	"message_count" INTEGER NOT NULL DEFAULT 0,
	-- Timestamp of the newest message. The sort key of the entire mailbox view, and the reason it is denormalised here.
	"last_message_at" TIMESTAMPTZ NOT NULL,
	-- First line of the newest message, precomputed for the list because extracting it from a body at render time means fetching every body on the page.
	"snippet" VARCHAR(300),
	-- True when any message in the thread is unread. Maintained on write because bolding a thread in a list must not require reading its messages.
	"has_unread" BOOLEAN NOT NULL DEFAULT true,
	-- True when any message carries one, so the paperclip filter is an indexed predicate.
	"has_attachments" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "threads" IS 'A conversation within one mailbox. Every field here is a rollup of its messages, maintained on write, because the mailbox list is the most-rendered view in the product and it must never aggregate.';
COMMENT ON COLUMN "threads"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "threads"."account_id" IS 'Mailbox the thread belongs to. Threads are per-account: two recipients of the same exchange have their own threads with their own state.';
COMMENT ON COLUMN "threads"."subject_normalised" IS 'Subject with Re: and Fwd: prefixes stripped. Used as a weak threading signal when References headers are missing, which for mail from web forms is common.';
COMMENT ON COLUMN "threads"."message_count" IS 'Cached size of the thread, so a list view never counts children.';
COMMENT ON COLUMN "threads"."last_message_at" IS 'Timestamp of the newest message. The sort key of the entire mailbox view, and the reason it is denormalised here.';
COMMENT ON COLUMN "threads"."snippet" IS 'First line of the newest message, precomputed for the list because extracting it from a body at render time means fetching every body on the page.';
COMMENT ON COLUMN "threads"."has_unread" IS 'True when any message in the thread is unread. Maintained on write because bolding a thread in a list must not require reading its messages.';
COMMENT ON COLUMN "threads"."has_attachments" IS 'True when any message carries one, so the paperclip filter is an indexed predicate.';

CREATE INDEX "idx_threads_account_recent"
ON "threads" ("account_id", "last_message_at");

CREATE TABLE IF NOT EXISTS "messages" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Mailbox the copy belongs to. Each recipient gets a row: a message is stored once per mailbox, and once only within it.
	"account_id" BIGINT NOT NULL,
	-- Conversation it belongs to, resolved at delivery from the References header and the normalised subject.
	"thread_id" BIGINT NOT NULL,
	-- The global Message-ID header. Unique per account, and the idempotency key that makes a redelivery a no-op.
	"rfc822_message_id" VARCHAR(400) NOT NULL,
	-- Message-ID this replies to, taken from the header. Null for a conversation opener.
	"in_reply_to" VARCHAR(400),
	-- Envelope sender as displayed. Recipients live in their own table because there are many of them.
	"from_address" VARCHAR(320) NOT NULL,
	-- Display name from the From header, which is attacker-controlled and shown with that in mind.
	"from_name" VARCHAR(160),
	-- Subject as sent. Empty string rather than null, because no subject is a real state and it should not complicate every query.
	"subject" VARCHAR(500) NOT NULL,
	-- Plain-text part. Null when the message is HTML only.
	"body_text" TEXT,
	-- HTML part, stored as received and sanitised at render rather than on ingest, so the original can always be re-examined.
	"body_html" TEXT,
	-- Total size including attachments, counted against the account quota.
	"size_bytes" INTEGER NOT NULL,
	-- Date header from the sender, which is self-reported and occasionally absurd.
	"sent_at" TIMESTAMPTZ NOT NULL,
	-- When this server accepted it. Sorting on this rather than sent_at is what stops a forged Date header pinning a message to the top of the mailbox.
	"received_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Per-message read state. A real column rather than an UNREAD label because it changes far more often than anything else in the mailbox and is read on every list render.
	"is_read" BOOLEAN NOT NULL DEFAULT false,
	-- Flagged by the user. Kept beside is_read for the same reason.
	"is_starred" BOOLEAN NOT NULL DEFAULT false,
	-- True while the message is unsent. Drafts live in this table so a draft and the reply it becomes are the same row.
	"is_draft" BOOLEAN NOT NULL DEFAULT false,
	-- Final score from the classifier, copied from the newest verdict so list filtering never joins.
	"spam_score" DECIMAL(5,2),
	-- When the message should return to the inbox. Null when not snoozed; a sweeper reapplies the INBOX label at this instant.
	"snoozed_until" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "messages" IS 'The message body, stored exactly once per mailbox regardless of how many labels it carries. That single fact is what makes the label model work: applying five labels costs five tiny join rows, not five copies of a megabyte of HTML.';
COMMENT ON COLUMN "messages"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "messages"."account_id" IS 'Mailbox the copy belongs to. Each recipient gets a row: a message is stored once per mailbox, and once only within it.';
COMMENT ON COLUMN "messages"."thread_id" IS 'Conversation it belongs to, resolved at delivery from the References header and the normalised subject.';
COMMENT ON COLUMN "messages"."rfc822_message_id" IS 'The global Message-ID header. Unique per account, and the idempotency key that makes a redelivery a no-op.';
COMMENT ON COLUMN "messages"."in_reply_to" IS 'Message-ID this replies to, taken from the header. Null for a conversation opener.';
COMMENT ON COLUMN "messages"."from_address" IS 'Envelope sender as displayed. Recipients live in their own table because there are many of them.';
COMMENT ON COLUMN "messages"."from_name" IS 'Display name from the From header, which is attacker-controlled and shown with that in mind.';
COMMENT ON COLUMN "messages"."subject" IS 'Subject as sent. Empty string rather than null, because no subject is a real state and it should not complicate every query.';
COMMENT ON COLUMN "messages"."body_text" IS 'Plain-text part. Null when the message is HTML only.';
COMMENT ON COLUMN "messages"."body_html" IS 'HTML part, stored as received and sanitised at render rather than on ingest, so the original can always be re-examined.';
COMMENT ON COLUMN "messages"."size_bytes" IS 'Total size including attachments, counted against the account quota.';
COMMENT ON COLUMN "messages"."sent_at" IS 'Date header from the sender, which is self-reported and occasionally absurd.';
COMMENT ON COLUMN "messages"."received_at" IS 'When this server accepted it. Sorting on this rather than sent_at is what stops a forged Date header pinning a message to the top of the mailbox.';
COMMENT ON COLUMN "messages"."is_read" IS 'Per-message read state. A real column rather than an UNREAD label because it changes far more often than anything else in the mailbox and is read on every list render.';
COMMENT ON COLUMN "messages"."is_starred" IS 'Flagged by the user. Kept beside is_read for the same reason.';
COMMENT ON COLUMN "messages"."is_draft" IS 'True while the message is unsent. Drafts live in this table so a draft and the reply it becomes are the same row.';
COMMENT ON COLUMN "messages"."spam_score" IS 'Final score from the classifier, copied from the newest verdict so list filtering never joins.';
COMMENT ON COLUMN "messages"."snoozed_until" IS 'When the message should return to the inbox. Null when not snoozed; a sweeper reapplies the INBOX label at this instant.';

CREATE UNIQUE INDEX "uq_messages_account_rfc822"
ON "messages" ("account_id", "rfc822_message_id");
CREATE INDEX "idx_messages_thread_time"
ON "messages" ("thread_id", "received_at");
CREATE INDEX "idx_messages_account_unread"
ON "messages" ("account_id", "is_read");

CREATE TABLE IF NOT EXISTS "message_labels" (
	-- Message being labelled. Composite key with label_id.
	"message_id" BIGINT,
	-- Label applied. The composite primary key means a label can be applied to a message at most once, enforced by the table rather than by code.
	"label_id" BIGINT,
	-- When it was applied. Lets the UI order a label view by when the message arrived in it rather than when it was sent.
	"applied_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- user | filter | system. Knowing a label came from a filter is what makes why is this in my promotions tab answerable.
	"applied_by" VARCHAR(16) NOT NULL DEFAULT 'user',
	PRIMARY KEY("message_id", "label_id")
);

COMMENT ON TABLE "message_labels" IS 'The join table that is the whole design. Opening a label is a lookup by label_id; archiving is deleting the INBOX row; deleting is adding the TRASH row. The message itself never moves, which is why a message can be in two places at once without being duplicated.';
COMMENT ON COLUMN "message_labels"."message_id" IS 'Message being labelled. Composite key with label_id.';
COMMENT ON COLUMN "message_labels"."label_id" IS 'Label applied. The composite primary key means a label can be applied to a message at most once, enforced by the table rather than by code.';
COMMENT ON COLUMN "message_labels"."applied_at" IS 'When it was applied. Lets the UI order a label view by when the message arrived in it rather than when it was sent.';
COMMENT ON COLUMN "message_labels"."applied_by" IS 'user | filter | system. Knowing a label came from a filter is what makes why is this in my promotions tab answerable.';

CREATE INDEX "idx_message_labels_by_label"
ON "message_labels" ("label_id", "message_id");

CREATE TABLE IF NOT EXISTS "message_recipients" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Message the recipient is on.
	"message_id" BIGINT NOT NULL,
	-- to | cc | bcc. Bcc rows exist only on the sender copy — storing them on a recipient copy would leak exactly what bcc exists to hide.
	"recipient_type" VARCHAR(4) NOT NULL,
	-- Recipient address as it appeared in the header.
	"address" VARCHAR(320) NOT NULL,
	-- Name from the header, where one was supplied.
	"display_name" VARCHAR(160),
	-- Order within its type, preserved because reply-all must reproduce the original ordering.
	"position" SMALLINT NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "message_recipients" IS 'Recipients as rows rather than a comma-separated header string. This is what makes search by recipient, reply-all and contact frequency ranking indexable instead of a substring match.';
COMMENT ON COLUMN "message_recipients"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "message_recipients"."message_id" IS 'Message the recipient is on.';
COMMENT ON COLUMN "message_recipients"."recipient_type" IS 'to | cc | bcc. Bcc rows exist only on the sender copy — storing them on a recipient copy would leak exactly what bcc exists to hide.';
COMMENT ON COLUMN "message_recipients"."address" IS 'Recipient address as it appeared in the header.';
COMMENT ON COLUMN "message_recipients"."display_name" IS 'Name from the header, where one was supplied.';
COMMENT ON COLUMN "message_recipients"."position" IS 'Order within its type, preserved because reply-all must reproduce the original ordering.';

CREATE INDEX "idx_recipients_message_type"
ON "message_recipients" ("message_id", "recipient_type", "position");
CREATE INDEX "idx_recipients_address"
ON "message_recipients" ("address");

CREATE TABLE IF NOT EXISTS "attachment_blobs" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Hex digest of the bytes. The deduplication key: the same file sent to a thousand mailboxes is stored once and referenced a thousand times.
	"content_sha256" CHAR(64) NOT NULL UNIQUE,
	-- Byte length, used for quota accounting and to short-circuit a hash comparison.
	"size_bytes" BIGINT NOT NULL,
	-- Detected MIME type, determined by sniffing rather than trusting the declared one.
	"content_type" VARCHAR(160) NOT NULL,
	-- Object storage path. Bytes live in object storage; the database holds only the reference.
	"storage_key" VARCHAR(500) NOT NULL,
	-- How many attachment rows point here. A blob is only deletable at zero, which is what stops one user emptying their trash from destroying another user copy.
	"reference_count" INTEGER NOT NULL DEFAULT 0,
	-- When the content first entered the system.
	"first_seen_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "attachment_blobs" IS 'Content-addressed storage for attachment bytes. Deduplicating by hash is the single largest storage saving in a mail system, because the same deck gets mailed to everyone in the company.';
COMMENT ON COLUMN "attachment_blobs"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "attachment_blobs"."content_sha256" IS 'Hex digest of the bytes. The deduplication key: the same file sent to a thousand mailboxes is stored once and referenced a thousand times.';
COMMENT ON COLUMN "attachment_blobs"."size_bytes" IS 'Byte length, used for quota accounting and to short-circuit a hash comparison.';
COMMENT ON COLUMN "attachment_blobs"."content_type" IS 'Detected MIME type, determined by sniffing rather than trusting the declared one.';
COMMENT ON COLUMN "attachment_blobs"."storage_key" IS 'Object storage path. Bytes live in object storage; the database holds only the reference.';
COMMENT ON COLUMN "attachment_blobs"."reference_count" IS 'How many attachment rows point here. A blob is only deletable at zero, which is what stops one user emptying their trash from destroying another user copy.';
COMMENT ON COLUMN "attachment_blobs"."first_seen_at" IS 'When the content first entered the system.';

CREATE TABLE IF NOT EXISTS "attachments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Message the attachment hangs off.
	"message_id" BIGINT NOT NULL,
	-- Deduplicated content. Many attachment rows can share one blob with different filenames.
	"blob_id" BIGINT NOT NULL,
	-- Name as sent, which belongs to the attachment rather than the bytes — the same file arrives as report.pdf and as final_v3.pdf.
	"filename" VARCHAR(255) NOT NULL,
	-- MIME type the sender claimed, kept alongside the sniffed one because a mismatch is a useful phishing signal.
	"declared_content_type" VARCHAR(160),
	-- True for images referenced from the HTML body rather than listed as attachments.
	"is_inline" BOOLEAN NOT NULL DEFAULT false,
	-- The Content-ID the HTML references for an inline part. Null otherwise.
	"content_id" VARCHAR(255),
	-- MIME part index, e.g. 1.2.3, so the original structure can be reconstructed exactly.
	"part_path" VARCHAR(60),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "attachments" IS 'The per-message facts about an attached file — its name, its position in the MIME tree, whether it is inline. The bytes are one level down in attachment_blobs, which is what lets ten thousand copies of the same PDF cost one PDF.';
COMMENT ON COLUMN "attachments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "attachments"."message_id" IS 'Message the attachment hangs off.';
COMMENT ON COLUMN "attachments"."blob_id" IS 'Deduplicated content. Many attachment rows can share one blob with different filenames.';
COMMENT ON COLUMN "attachments"."filename" IS 'Name as sent, which belongs to the attachment rather than the bytes — the same file arrives as report.pdf and as final_v3.pdf.';
COMMENT ON COLUMN "attachments"."declared_content_type" IS 'MIME type the sender claimed, kept alongside the sniffed one because a mismatch is a useful phishing signal.';
COMMENT ON COLUMN "attachments"."is_inline" IS 'True for images referenced from the HTML body rather than listed as attachments.';
COMMENT ON COLUMN "attachments"."content_id" IS 'The Content-ID the HTML references for an inline part. Null otherwise.';
COMMENT ON COLUMN "attachments"."part_path" IS 'MIME part index, e.g. 1.2.3, so the original structure can be reconstructed exactly.';

CREATE INDEX "idx_attachments_message"
ON "attachments" ("message_id");
CREATE INDEX "idx_attachments_blob"
ON "attachments" ("blob_id");

CREATE TABLE IF NOT EXISTS "drafts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Author mailbox.
	"account_id" BIGINT NOT NULL,
	-- The message row holding the current content. Unique, so a draft is always exactly one message.
	"message_id" BIGINT NOT NULL UNIQUE,
	-- Thread being replied to. Null for a new composition, which is what makes an orphan draft distinguishable from a reply in progress.
	"thread_id" BIGINT,
	-- Specific message being replied to within the thread.
	"in_reply_to_message_id" BIGINT,
	-- Incremented on each autosave. Lets two open tabs detect that one has overwritten the other instead of silently losing a paragraph.
	"autosave_version" INTEGER NOT NULL DEFAULT 1,
	-- Last autosave time, shown as Saved at.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Scheduled send time. Null for immediate send; a scheduler picks up rows whose time has passed.
	"send_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "drafts" IS 'A stable handle for an unsent message across autosaves. The content stays in messages so that sending a draft is a state change rather than a copy — the row keeps its identity and stays in the thread it belongs to.';
COMMENT ON COLUMN "drafts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "drafts"."account_id" IS 'Author mailbox.';
COMMENT ON COLUMN "drafts"."message_id" IS 'The message row holding the current content. Unique, so a draft is always exactly one message.';
COMMENT ON COLUMN "drafts"."thread_id" IS 'Thread being replied to. Null for a new composition, which is what makes an orphan draft distinguishable from a reply in progress.';
COMMENT ON COLUMN "drafts"."in_reply_to_message_id" IS 'Specific message being replied to within the thread.';
COMMENT ON COLUMN "drafts"."autosave_version" IS 'Incremented on each autosave. Lets two open tabs detect that one has overwritten the other instead of silently losing a paragraph.';
COMMENT ON COLUMN "drafts"."updated_at" IS 'Last autosave time, shown as Saved at.';
COMMENT ON COLUMN "drafts"."send_at" IS 'Scheduled send time. Null for immediate send; a scheduler picks up rows whose time has passed.';

CREATE INDEX "idx_drafts_account_updated"
ON "drafts" ("account_id", "updated_at");

CREATE TABLE IF NOT EXISTS "filters" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owner of the rule.
	"account_id" BIGINT NOT NULL,
	-- Optional label for the rule in settings.
	"name" VARCHAR(120),
	-- all | any. Whether every condition must match or just one, which is the only boolean logic a mail filter needs.
	"match_mode" VARCHAR(8) NOT NULL DEFAULT 'all',
	-- Evaluation order, low first. Deterministic ordering matters because two rules can both want to archive the same message.
	"priority" INTEGER NOT NULL DEFAULT 0,
	-- Stops evaluating later filters once this one matches, which is how a catch-all rule is kept from undoing a specific one.
	"stop_processing" BOOLEAN NOT NULL DEFAULT false,
	-- False pauses the rule without losing its conditions, which is how people debug their own filters.
	"is_enabled" BOOLEAN NOT NULL DEFAULT true,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "filters" IS 'A user rule evaluated at delivery. Split across three tables rather than stored as one expression string, because the settings UI has to render it, edit it, and reason about the order rules run in.';
COMMENT ON COLUMN "filters"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "filters"."account_id" IS 'Owner of the rule.';
COMMENT ON COLUMN "filters"."name" IS 'Optional label for the rule in settings.';
COMMENT ON COLUMN "filters"."match_mode" IS 'all | any. Whether every condition must match or just one, which is the only boolean logic a mail filter needs.';
COMMENT ON COLUMN "filters"."priority" IS 'Evaluation order, low first. Deterministic ordering matters because two rules can both want to archive the same message.';
COMMENT ON COLUMN "filters"."stop_processing" IS 'Stops evaluating later filters once this one matches, which is how a catch-all rule is kept from undoing a specific one.';
COMMENT ON COLUMN "filters"."is_enabled" IS 'False pauses the rule without losing its conditions, which is how people debug their own filters.';
COMMENT ON COLUMN "filters"."created_at" IS 'Creation time.';

CREATE INDEX "idx_filters_account_priority"
ON "filters" ("account_id", "priority");

CREATE TABLE IF NOT EXISTS "filter_conditions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Rule this condition belongs to.
	"filter_id" BIGINT NOT NULL,
	-- from | to | cc | subject | body | has_attachment | size | list_id.
	"field" VARCHAR(24) NOT NULL,
	-- contains | equals | starts_with | matches_regex | greater_than.
	"operator" VARCHAR(16) NOT NULL DEFAULT 'contains',
	-- Value compared against. Kept as text even for size comparisons, because one column serving every field type is what keeps the rule editor generic.
	"value" VARCHAR(500) NOT NULL,
	-- Inverts the condition, so does not contain needs no second operator.
	"negate" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "filter_conditions" IS 'One clause of a rule. Structured rather than stored as a query string so the settings page can render the rule that exists, rather than a parsed guess at it.';
COMMENT ON COLUMN "filter_conditions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "filter_conditions"."filter_id" IS 'Rule this condition belongs to.';
COMMENT ON COLUMN "filter_conditions"."field" IS 'from | to | cc | subject | body | has_attachment | size | list_id.';
COMMENT ON COLUMN "filter_conditions"."operator" IS 'contains | equals | starts_with | matches_regex | greater_than.';
COMMENT ON COLUMN "filter_conditions"."value" IS 'Value compared against. Kept as text even for size comparisons, because one column serving every field type is what keeps the rule editor generic.';
COMMENT ON COLUMN "filter_conditions"."negate" IS 'Inverts the condition, so does not contain needs no second operator.';

CREATE INDEX "idx_conditions_filter"
ON "filter_conditions" ("filter_id");

CREATE TABLE IF NOT EXISTS "filter_actions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Rule this action belongs to.
	"filter_id" BIGINT NOT NULL,
	-- apply_label | remove_label | mark_read | star | archive | delete | forward | never_spam.
	"action" VARCHAR(24) NOT NULL,
	-- Label to apply or remove. Null for actions that take no label.
	"label_id" BIGINT,
	-- Destination for a forward action. Null otherwise, and verified before the rule can be saved.
	"forward_address" VARCHAR(320),
	-- Order the actions run in, which matters when one labels and another archives.
	"position" SMALLINT NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "filter_actions" IS 'What a matching rule does. Actions are rows because a filter usually does several things at once, and because archive is just removing the INBOX label — the action list and the label model are the same mechanism.';
COMMENT ON COLUMN "filter_actions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "filter_actions"."filter_id" IS 'Rule this action belongs to.';
COMMENT ON COLUMN "filter_actions"."action" IS 'apply_label | remove_label | mark_read | star | archive | delete | forward | never_spam.';
COMMENT ON COLUMN "filter_actions"."label_id" IS 'Label to apply or remove. Null for actions that take no label.';
COMMENT ON COLUMN "filter_actions"."forward_address" IS 'Destination for a forward action. Null otherwise, and verified before the rule can be saved.';
COMMENT ON COLUMN "filter_actions"."position" IS 'Order the actions run in, which matters when one labels and another archives.';

CREATE INDEX "idx_actions_filter_position"
ON "filter_actions" ("filter_id", "position");

CREATE TABLE IF NOT EXISTS "spam_verdicts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Message scored.
	"message_id" BIGINT NOT NULL,
	-- Classifier that produced this verdict, e.g. bayes_v4 or reputation. Several run per message and each gets a row.
	"engine" VARCHAR(40) NOT NULL,
	-- Contribution to the spam score. Signed, because a strong authentication pass legitimately pulls a message back toward the inbox.
	"score" DECIMAL(5,2) NOT NULL,
	-- ham | spam | phishing | uncertain. phishing is separated from spam because it is quarantined rather than filed.
	"verdict" VARCHAR(16) NOT NULL,
	-- pass | fail | softfail | none from the SPF check.
	"spf_result" VARCHAR(12),
	-- pass | fail | none from the DKIM signature check.
	"dkim_result" VARCHAR(12),
	-- pass | fail | none. Together these three are the difference between a suspicious message and a forged one.
	"dmarc_result" VARCHAR(12),
	-- Rules that fired with their weights, kept so a false positive can be explained and the classifier retuned.
	"matched_rules" JSONB,
	-- When the verdict was produced. Rescoring after a user reports a message adds a row rather than editing one.
	"evaluated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "spam_verdicts" IS 'One score from one engine, append-only. Keeping the full evidence — authentication results and the rules that fired — is the only way to answer why a message people were expecting ended up in spam.';
COMMENT ON COLUMN "spam_verdicts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "spam_verdicts"."message_id" IS 'Message scored.';
COMMENT ON COLUMN "spam_verdicts"."engine" IS 'Classifier that produced this verdict, e.g. bayes_v4 or reputation. Several run per message and each gets a row.';
COMMENT ON COLUMN "spam_verdicts"."score" IS 'Contribution to the spam score. Signed, because a strong authentication pass legitimately pulls a message back toward the inbox.';
COMMENT ON COLUMN "spam_verdicts"."verdict" IS 'ham | spam | phishing | uncertain. phishing is separated from spam because it is quarantined rather than filed.';
COMMENT ON COLUMN "spam_verdicts"."spf_result" IS 'pass | fail | softfail | none from the SPF check.';
COMMENT ON COLUMN "spam_verdicts"."dkim_result" IS 'pass | fail | none from the DKIM signature check.';
COMMENT ON COLUMN "spam_verdicts"."dmarc_result" IS 'pass | fail | none. Together these three are the difference between a suspicious message and a forged one.';
COMMENT ON COLUMN "spam_verdicts"."matched_rules" IS 'Rules that fired with their weights, kept so a false positive can be explained and the classifier retuned.';
COMMENT ON COLUMN "spam_verdicts"."evaluated_at" IS 'When the verdict was produced. Rescoring after a user reports a message adds a row rather than editing one.';

CREATE INDEX "idx_verdicts_message_time"
ON "spam_verdicts" ("message_id", "evaluated_at");

